package vn.smarttravel.community.collections.repository;
import java.util.*;
import org.bson.Document;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import vn.smarttravel.community.reviews.client.CatalogClient;

@Repository
public class CollectionRepository {
    private final MongoTemplate mongo;private final CatalogClient catalog;
    public CollectionRepository(MongoTemplate mongo,CatalogClient catalog){this.mongo=mongo;this.catalog=catalog;}
    private Query id(String id){UUID.fromString(id);return Query.query(Criteria.where("_id").is(id));}
    public Document get(String id,String user,boolean owner){
        var result=mongo.findOne(id(id),Document.class,"collections");if(result==null||(!Objects.equals(result.getString("owner_id"),user)&&(owner||!"PUBLIC".equals(result.getString("visibility")))))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return result;
    }
    private void touch(String id,String user,long version){var result=mongo.updateFirst(Query.query(Criteria.where("_id").is(id).and("owner_id").is(user).and("version").is(version)),new Update().inc("version",1L).set("updated_at",new Date()),"collections");if(result.getMatchedCount()!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Collection version conflict");}
    private String name(Object name){String value=Objects.toString(name,"").trim();if(value.isEmpty()||value.length()>1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid collection name");return value;}
    private String visibility(Object value){String text=Objects.toString(value,"PRIVATE");if(!Set.of("PRIVATE","PUBLIC").contains(text))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);return text;}
    @Transactional public Document create(String user,Map<String,Object> request){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);Date now=new Date();String id=UUID.randomUUID().toString();var row=new Document("_id",id).append("owner_id",user).append("name",name(request.get("name"))).append("visibility",visibility(request.get("visibility"))).append("version",1L).append("created_at",now).append("updated_at",now);mongo.insert(row,"collections");visibilityEvent(row);return row;}
    private void visibilityEvent(Document row){mongo.insert(new Document("_id",UUID.randomUUID().toString()).append("collection_id",row.getString("_id")).append("version",row.get("version")).append("visibility",row.getString("visibility")).append("occurred_at",new Date()),"collection_visibility_events");}
    @Transactional public Document update(String id,String user,long version,Map<String,Object> request){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(id,user,true);touch(id,user,version);var update=new Update();if(request.containsKey("name"))update.set("name",name(request.get("name")));if(request.containsKey("visibility"))update.set("visibility",visibility(request.get("visibility")));if(!update.getUpdateObject().isEmpty())mongo.updateFirst(id(id),update,"collections");var row=get(id,user,true);visibilityEvent(row);return row;}
    @Transactional public void delete(String id,String user,long version){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(id,user,true);touch(id,user,version);mongo.remove(Query.query(Criteria.where("collection_id").is(id)),"collection_items");mongo.remove(id(id),"collections");}
    public List<Document> list(String user){return mongo.find(Query.query(Criteria.where("owner_id").is(user)).limit(100).with(Sort.by(Sort.Order.desc("updated_at"),Sort.Order.asc("_id"))),Document.class,"collections");}
    private List<Document> storedItems(String id,String user){get(id,user,false);return mongo.find(Query.query(Criteria.where("collection_id").is(id)).limit(100).with(Sort.by("rank","_id")),Document.class,"collection_items");}
    public List<Document> items(String id,String user){var rows=storedItems(id,user);var snapshots=catalog.batch(rows.stream().map(row->row.getString("place_id")).distinct().toList());for(var row:rows)row.put("catalog_place",snapshots.get(row.getString("place_id")));return rows;}
    @Transactional public Document add(String id,String user,long version,Map<String,Object> body){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(id,user,true);String place=UUID.fromString(body.get("place_id").toString()).toString();catalog.validate(place);touch(id,user,version);long count=mongo.count(Query.query(Criteria.where("collection_id").is(id)),"collection_items");if(count>=100)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Collection item limit");var row=new Document("_id",UUID.randomUUID().toString()).append("collection_id",id).append("place_id",place).append("rank",count).append("version",version+1).append("note",note(body.get("note")));mongo.insert(row,"collection_items");return row;}
    private String note(Object value){String note=Objects.toString(value," ");if(note.length()>1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Note too long");return note;}
    public Document item(String collection,String item,String user){get(collection,user,false);var row=mongo.findOne(Query.query(Criteria.where("_id").is(item).and("collection_id").is(collection)),Document.class,"collection_items");if(row==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);row.put("catalog_place",catalog.batch(List.of(row.getString("place_id"))).get(row.getString("place_id")));return row;}
    @Transactional public Document updateItem(String collection,String item,String user,long version,Map<String,Object> body){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(collection,user,true);var row=item(collection,item,user);touch(collection,user,version);mongo.updateFirst(id(item),new Update().set("note",note(body.get("note"))).set("version",version+1),"collection_items");row.put("note",note(body.get("note")));row.put("version",version+1);return row;}
    @Transactional public void deleteItem(String collection,String item,String user,long version){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(collection,user,true);item(collection,item,user);touch(collection,user,version);mongo.remove(id(item),"collection_items");}
    @Transactional public List<Document> reorder(String id,String user,long version,List<String> order){vn.smarttravel.community.infrastructure.persistence.repository.UserMutationFence.acquire(mongo,user);get(id,user,true);var items=storedItems(id,user);var expected=new HashSet<>(items.stream().map(d->d.getString("_id")).toList());if(order==null||order.size()!=expected.size()||new HashSet<>(order).size()!=order.size()||!expected.equals(new HashSet<>(order)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Order must contain every item exactly once");touch(id,user,version);for(int rank=0;rank<order.size();rank++)mongo.updateFirst(Query.query(Criteria.where("_id").is(order.get(rank)).and("collection_id").is(id)),new Update().set("rank",rank),"collection_items");return storedItems(id,user);}
}
